Definition x1_frame (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (m m3 : amem)
    (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (SPV lo FF : Z) : Prop :=
  FF mod 64 = 0 /\ ablk FF (FF + 64) /\ FF + 64 <= ATOP /\ rng RNG FF 64 /\ rng RNG (shad FF) 8
  /\ (forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF)
  /\ AHEAP AI L RNG st (FB0 FF :: LB) m3
  /\ magree asegs (aclient_addr CI LB SPV) m m3 /\ mem_inv asegs m3
  /\ rw_cells asegs m3 (SPV + -104) (FRBx ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11)
  /\ rw_cells asegs m3 (shad FF) FDSH
  /\ stk asegs m3 lo (SPAx SPV - 16) /\ stk asegs m3 (SPAx SPV + 312) (SPV + -104).

(* [comment removed for export] *)
Lemma x1_open : forall (L : alayout) (RNG : footprint)
    (ra gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (FR : bvmap 5 word) (fc : bv 32) (m : amem) (st : astate) (LB : list ablock)
    (SPV DT W S size flags lo : Z) (Q : machine_state -> Prop),
  AHEAP AI L RNG st LB m -> (forall F k, ~ In (mkABlock (ABFake 0) F k) LB) ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  stk asegs m lo SPV -> ATOP + 4096 <= lo -> lo <= SPV - HUF_RDT_STACK_A2 ->
  SPV + 16 < al_top L -> SPV mod 16 = 0 ->
  mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
  rng RNG lo (al_top L - lo) -> rng_aimg RNG -> rng_fs L RNG ->
  (forall (FF : Z) (m3 : amem) (j0' j24 j36 j52 j104 j136 : list byte) (y5 y6 y7 y28 y29 y30 y31 : word),
     x1_frame L RNG st LB m m3 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 SPV lo FF ->
     rw_cells asegs m3 (SPAx SPV - 16) [C8 (Z_to_bv 64 876); C8 (Z_to_bv 64 flags)] ->
     rw_cells asegs m3 (SPAx SPV) [CB 80 j0'; C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)); C8 (Z_to_bv 64 FF);
                                   C8 (Z_to_bv 64 FF); CB 16 j104; C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 W); CB 168 j136;
                                   C8 (Z_to_bv 64 FF)] ->
     rw_cells asegs m3 FF (X1HDR FF (fflag L 0 FF) j24 j36 j52) ->
     evtF asegs RNG Q
       (MS (mkR (Z_to_bv 64 0x80434) (Z_to_bv 64 (SPAx SPV - 16)) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAx SPV))
                (Z_to_bv 64 (W + 1236)) (Z_to_bv 64 256) (Z_to_bv 64 W) (Z_to_bv 64 (FF + 48)) (Z_to_bv 64 (FF + 32))
                (Z_to_bv 64 S) (Z_to_bv 64 size) (Z_to_bv 64 (W + 104))
                (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (W + 1236))
                (Z_to_bv 64 (-44)) (Z_to_bv 64 size) (Z_to_bv 64 S) (Z_to_bv 64 flags) (Z_to_bv 64 (FF + 32))
                (Z_to_bv 64 (FF + 48)) y28 y29 y30 y31)
           FR (Z_to_bv 64 0x95144) fc None m3 (seg_rom asegs))) ->
  evtF asegs RNG Q
    (MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DT) (Z_to_bv 64 S) (Z_to_bv 64 size) (Z_to_bv 64 W)
             (Z_to_bv 64 8704) (Z_to_bv 64 flags) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        FR (Z_to_bv 64 0x802b0) fc None m (seg_rom asegs)).
Proof.
