Lemma x1_close : forall (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (m m4 : amem) (st : astate) (LB : list ablock) (SPV DT W mtl lo FF rv : Z) (pdt pw : aptr)
    (j0 : word) (ja jb : list byte)
    (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word),
  AHEAP AI L RNG st (FB0 FF :: LB) m4 ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  FF mod 64 = 0 -> ablk FF (FF + 64) -> FF + 64 <= ATOP -> rng RNG FF 64 -> rng RNG (shad FF) 8 ->
  (forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF) ->
  magree asegs (PAGx LB SPV DT mtl W) m m4 -> mem_inv asegs m4 ->
  rw_cells asegs m4 (Z.shiftr FF 3 + 2147450880) FDSH ->
  rw_cells asegs m4 FF [C8 j0] -> rw_cells asegs m4 (FF + 56) [C8 (Z_to_bv 64 (fflag L 0 FF))] ->
  rw_cells asegs m4 (SPV + -104) (FRBx ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11) ->
  rw_cells asegs m4 (SPAx SPV) [CB 80 ja; C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)); C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 FF);
                                CB 208 jb] ->
  stk asegs m4 lo (SPAx SPV) -> stk asegs m4 (SPAx SPV + 312) (SPV + -104) ->
  ATOP + 4096 <= lo -> lo <= SPV - HUF_RDT_STACK_A2 -> SPV + 16 < al_top L -> SPV mod 16 = 0 -> rng RNG lo (al_top L - lo) ->
  1 <= mtl <= 12 -> In (HB pdt DT (DTABLE_BYTES mtl)) LB ->
  0 <= rv < 2^64 -> (rv < 2^64 - 119 -> huf_dt_okA m4 DT mtl) ->
  evtF asegs RNG (huf_rdt_postA AI huf_dt_okA L RNG ra (Z_to_bv 64 SPV) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB
                    DT W mtl lo m)
    (MS (mkR x1 (Z_to_bv 64 (SPAx SPV)) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAx SPV)) x10 x11 x12 x13 x14 x15 x16 x17
             x18 x19 x20 x21 (Z_to_bv 64 rv) x23 x24 x25 x26 x27 x28 x29 x30 x31)
        FR (Z_to_bv 64 0x81250) fc None m4 (seg_rom asegs)).
